SELECT EXISTS (
SELECT 1
FROM drink_details dd
JOIN drinks d ON d.drink_id = dd.drink_id
WHERE dd.drink_id = #{drinkId}
AND UPPER(TRIM(dd.size)) = #{size}
AND dd.deleted_at IS NULL
AND d.deleted_at IS NULL
AND d.is_deleted = FALSE

  AND dd.drink_detail_id != #{excludedDrinkDetailId}

)

